import React, { useState } from 'react';

function ClientePublico() {
  const [abaAtiva, setAbaAtiva] = useState('servicos');
  const [avaliacoes, setAvaliacoes] = useState([
    { id: 1, nome: 'João Silva', estrelas: 5, texto: 'Excelente atendimento!', data: '2026-07-25' },
    { id: 2, nome: 'Carlos Santos', estrelas: 5, texto: 'Marco é o melhor!', data: '2026-07-20' },
  ]);
  const [novaAvaliacao, setNovaAvaliacao] = useState({
    nome: '',
    estrelas: 5,
    texto: ''
  });

  const servicos = [
    { id: 1, nome: 'Corte', preco: '¥4.000', duracao: '45 min', descricao: 'Corte de cabelo masculino' },
    { id: 2, nome: 'Corte + Sobrancelhas', preco: '¥4.500', duracao: '45 min', descricao: 'Corte completo' },
    { id: 3, nome: 'Corte + Barba', preco: '¥6.500', duracao: '60 min', descricao: 'Corte e modelagem de barba' },
    { id: 4, nome: 'Coloração', preco: '¥15.000', duracao: '90 min', descricao: 'Coloração profissional' },
    { id: 5, nome: 'Alisamento', preco: '¥15.000', duracao: '90 min', descricao: 'Alisamento e tratamento' },
  ];

  const profissionais = [
    { id: 1, nome: 'Marco Kaizen', especialidade: 'Cortes e Barba', exp: '14 anos' },
    { id: 2, nome: 'Gabriel Little Kaizen', especialidade: 'Cortes', exp: 'Certificado' },
    { id: 3, nome: 'Neia', especialidade: 'Coloração e Estética', exp: 'Especialista' },
  ];

  const horarios = [
    { dia: 'Segunda', inicio: '09:00', fim: '20:30' },
    { dia: 'Terça', inicio: '09:00', fim: '20:30' },
    { dia: 'Quarta', inicio: '09:00', fim: '20:30' },
    { dia: 'Quinta', inicio: '09:00', fim: '20:30' },
    { dia: 'Sexta', inicio: '09:00', fim: '20:30' },
    { dia: 'Sábado', inicio: '09:00', fim: '19:00' },
    { dia: 'Domingo', inicio: 'Fechado', fim: '' },
  ];

  const handleAdicionarAvaliacao = (e) => {
    e.preventDefault();
    if (novaAvaliacao.nome && novaAvaliacao.texto) {
      const hoje = new Date().toISOString().split('T')[0];
      setAvaliacoes([...avaliacoes, {
        id: avaliacoes.length + 1,
        ...novaAvaliacao,
        data: hoje
      }]);
      setNovaAvaliacao({ nome: '', estrelas: 5, texto: '' });
    }
  };

  const renderizarEstrelas = (num) => {
    return '⭐'.repeat(num);
  };

  return (
    <div className="cliente-publico-container">
      {/* Header */}
      <header className="cliente-header">
        <div className="cliente-header-content">
          <img src="/images/logo.png" alt="Kaizen" className="cliente-logo" />
          <div className="cliente-header-info">
            <h1>Kaizen Barber Shop</h1>
            <p>Sua barbearia premium em Anjo, Aichi</p>
          </div>
        </div>
      </header>

      {/* Abas Horizontais */}
      <nav className="cliente-abas">
        <button 
          className={`aba-btn ${abaAtiva === 'servicos' ? 'ativa' : ''}`}
          onClick={() => setAbaAtiva('servicos')}
        >
          💈 Serviços
        </button>
        <button 
          className={`aba-btn ${abaAtiva === 'detalhes' ? 'ativa' : ''}`}
          onClick={() => setAbaAtiva('detalhes')}
        >
          ℹ️ Detalhes
        </button>
        <button 
          className={`aba-btn ${abaAtiva === 'endereco' ? 'ativa' : ''}`}
          onClick={() => setAbaAtiva('endereco')}
        >
          📍 Endereço
        </button>
        <button 
          className={`aba-btn ${abaAtiva === 'pagamento' ? 'ativa' : ''}`}
          onClick={() => setAbaAtiva('pagamento')}
        >
          💳 Pagamento
        </button>
        <button 
          className={`aba-btn ${abaAtiva === 'redes' ? 'ativa' : ''}`}
          onClick={() => setAbaAtiva('redes')}
        >
          📱 Redes Sociais
        </button>
        <button 
          className={`aba-btn ${abaAtiva === 'profissionais' ? 'ativa' : ''}`}
          onClick={() => setAbaAtiva('profissionais')}
        >
          👥 Profissionais
        </button>
        <button 
          className={`aba-btn ${abaAtiva === 'fidelidade' ? 'ativa' : ''}`}
          onClick={() => setAbaAtiva('fidelidade')}
        >
          🎁 Fidelidade
        </button>
        <button 
          className={`aba-btn ${abaAtiva === 'avaliacoes' ? 'ativa' : ''}`}
          onClick={() => setAbaAtiva('avaliacoes')}
        >
          ⭐ Avaliações
        </button>
      </nav>

      {/* Conteúdo das Abas */}
      <main className="cliente-conteudo">

        {/* SERVIÇOS */}
        {abaAtiva === 'servicos' && (
          <section className="aba-section">
            <h2>💈 Nossos Serviços</h2>
            <div className="servicos-lista">
              {servicos.map((servico) => (
                <div key={servico.id} className="servico-card">
                  <div className="servico-info">
                    <h3>{servico.nome}</h3>
                    <p className="servico-desc">{servico.descricao}</p>
                    <p className="servico-duracao">⏱️ {servico.duracao}</p>
                  </div>
                  <div className="servico-preco">
                    <p className="preco">{servico.preco}</p>
                    <button className="btn-agendar-servico">Agendar</button>
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}

        {/* DETALHES */}
        {abaAtiva === 'detalhes' && (
          <section className="aba-section">
            <h2>ℹ️ Horários de Atendimento</h2>
            <div className="horarios-grid">
              {horarios.map((h, idx) => (
                <div key={idx} className="horario-card">
                  <h4>{h.dia}</h4>
                  <p>{h.inicio === 'Fechado' ? '🔴 Fechado' : `${h.inicio} - ${h.fim}`}</p>
                </div>
              ))}
            </div>
          </section>
        )}

        {/* ENDEREÇO */}
        {abaAtiva === 'endereco' && (
          <section className="aba-section">
            <h2>📍 Nossa Localização</h2>
            <div className="endereco-card">
              <h3>Kaizen Barber Shop</h3>
              <p><strong>Endereço:</strong><br />
              Aichi-Ken Anjo-Shi Hamatomi-Cho 4-17<br />
              San City Oomy 302<br />
              (Do outro lado da rua em relação ao McDonald's do Korona World)</p>
              <a href="https://maps.google.com/?q=Anjo+Aichi+Hamatomi" className="btn-mapa">
                🗺️ Ver no Google Maps
              </a>
            </div>
          </section>
        )}

        {/* FORMAS DE PAGAMENTO */}
        {abaAtiva === 'pagamento' && (
          <section className="aba-section">
            <h2>💳 Formas de Pagamento</h2>
            <div className="pagamento-grid">
              <div className="pagamento-card">
                <h3>💵 Dinheiro</h3>
                <p>Pagamento em dinheiro (Yen)</p>
              </div>
              <div className="pagamento-card">
                <h3>💳 Cartão de Crédito</h3>
                <p>Visa, Mastercard e AmEx</p>
              </div>
              <div className="pagamento-card">
                <h3>📱 PayPay</h3>
                <p>Pagamento via aplicativo PayPay</p>
              </div>
            </div>
          </section>
        )}

        {/* REDES SOCIAIS */}
        {abaAtiva === 'redes' && (
          <section className="aba-section">
            <h2>📱 Redes Sociais</h2>
            <div className="redes-grid">
              <a href="https://instagram.com/marco.kaizen" className="rede-card instagram">
                <h3>📸 Instagram</h3>
                <p>@marco.kaizen</p>
                <button>Seguir</button>
              </a>
              <a href="https://wa.me/81901234567" className="rede-card whatsapp">
                <h3>💬 WhatsApp</h3>
                <p>+81 90-1234-5678</p>
                <button>Mensagem</button>
              </a>
            </div>
          </section>
        )}

        {/* PROFISSIONAIS */}
        {abaAtiva === 'profissionais' && (
          <section className="aba-section">
            <h2>👥 Nossos Profissionais</h2>
            <div className="profissionais-lista">
              {profissionais.map((prof) => (
                <div key={prof.id} className="prof-item">
                  <img src={`/images/${prof.nome === 'Marco Kaizen' ? 'marco.png' : prof.nome === 'Gabriel Little Kaizen' ? 'gabriel.jpg' : 'neia.jpeg'}`} alt={prof.nome} />
                  <div className="prof-details">
                    <h3>{prof.nome}</h3>
                    <p><strong>{prof.especialidade}</strong></p>
                    <p className="prof-exp">{prof.exp}</p>
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}

        {/* FIDELIDADE */}
        {abaAtiva === 'fidelidade' && (
          <section className="aba-section">
            <h2>🎁 Programa de Fidelidade</h2>
            <div className="fidelidade-card">
              <h3>Ganhe pontos a cada visita!</h3>
              <p>✅ 2 pontos por serviço realizado</p>
              <p>✅ 10 pontos = ¥500 de desconto</p>
              <p>✅ Válido por 3 meses</p>
              <p>✅ Intransferível</p>
              <button className="btn-fidelidade">Participar do Programa</button>
            </div>
          </section>
        )}

        {/* AVALIAÇÕES */}
        {abaAtiva === 'avaliacoes' && (
          <section className="aba-section">
            <h2>⭐ Avaliações</h2>

            <div className="avaliacoes-novo">
              <h3>📝 Deixe sua avaliação e ganhe 20% de desconto!</h3>
              <form onSubmit={handleAdicionarAvaliacao}>
                <input
                  type="text"
                  placeholder="Seu nome"
                  value={novaAvaliacao.nome}
                  onChange={(e) => setNovaAvaliacao({...novaAvaliacao, nome: e.target.value})}
                  required
                />
                <select
                  value={novaAvaliacao.estrelas}
                  onChange={(e) => setNovaAvaliacao({...novaAvaliacao, estrelas: parseInt(e.target.value)})}
                >
                  <option value="1">⭐ 1 estrela</option>
                  <option value="2">⭐⭐ 2 estrelas</option>
                  <option value="3">⭐⭐⭐ 3 estrelas</option>
                  <option value="4">⭐⭐⭐⭐ 4 estrelas</option>
                  <option value="5">⭐⭐⭐⭐⭐ 5 estrelas</option>
                </select>
                <textarea
                  placeholder="Sua avaliação (serviço, profissional, ambiente)"
                  value={novaAvaliacao.texto}
                  onChange={(e) => setNovaAvaliacao({...novaAvaliacao, texto: e.target.value})}
                  required
                ></textarea>
                <button type="submit" className="btn-enviar-avaliacao">Enviar Avaliação e Ganhar 20% OFF</button>
              </form>
            </div>

            <div className="avaliacoes-lista">
              {avaliacoes.map((avaliacao) => (
                <div key={avaliacao.id} className="avaliacao-card">
                  <div className="avaliacao-header">
                    <h4>{avaliacao.nome}</h4>
                    <span className="estrelas">{renderizarEstrelas(avaliacao.estrelas)}</span>
                  </div>
                  <p className="avaliacao-texto">{avaliacao.texto}</p>
                  <p className="avaliacao-data">{avaliacao.data}</p>
                </div>
              ))}
            </div>
          </section>
        )}
      </main>

      {/* Footer */}
      <footer className="cliente-footer">
        <p>&copy; 2026 Kaizen Barber Shop. Todos os direitos reservados.</p>
      </footer>

      {/* Botão Acesso Profissional */}
      <div style={{ textAlign: 'center', padding: '20px', background: 'var(--secondary-dark)', borderTop: '2px solid var(--accent-gold)' }}>
        <button onClick={() => window.location.href = '/admin'} style={{
          background: 'var(--accent-gold)',
          color: 'var(--primary-dark)',
          border: 'none',
          padding: '12px 30px',
          borderRadius: '6px',
          fontWeight: 'bold',
          cursor: 'pointer',
          fontSize: '14px'
        }}>
          🔐 Acesso Profissional
        </button>
      </div>
    </div>
  );
}

export default ClientePublico;
